interface TrieNode {
  children: Map<string, TrieNode>;
  frequency: number;
  isEndOfWord: boolean;
}

function createNode(): TrieNode {
  return { children: new Map(), frequency: 0, isEndOfWord: false };
}

class AutocompleteTrie {
  private root: TrieNode = createNode();

  /**
   * Inserts a search term into the trie, accumulating its frequency
   * at the terminal node so repeated inserts of the same term add up.
   */
  insert(word: string, freq: number): void {
    let node = this.root;

    // Walk the raw word one codepoint at a time, creating branches as needed.
    for (const ch of word) {
      let child = node.children.get(ch);
      if (!child) {
        child = createNode();
        node.children.set(ch, child);
      }
      node = child;
    }

    node.isEndOfWord = true;
    node.frequency += freq;
  }

  /**
   * Returns the top `limit` known terms that start with `prefix`,
   * ranked by descending frequency.
   */
  suggest(prefix: string, limit: number = 5): Array<{ term: string; frequency: number }> {
    let node = this.root;

    // Walk the raw prefix down to its subtree root.
    for (const ch of prefix) {
      const child = node.children.get(ch);
      if (!child) {
        return [];
      }
      node = child;
    }

    const results: Array<{ term: string; frequency: number }> = [];
    this.collect(node, prefix, results);

    results.sort((a, b) => b.frequency - a.frequency);
    return results.slice(0, limit);
  }

  private collect(
    node: TrieNode,
    termSoFar: string,
    results: Array<{ term: string; frequency: number }>,
  ): void {
    if (node.isEndOfWord) {
      results.push({ term: termSoFar, frequency: node.frequency });
    }

    for (const [ch, child] of node.children) {
      this.collect(child, termSoFar + ch, results);
    }
  }
}

// Seed data used in the existing test suite — all ASCII, all lowercase.
const trie = new AutocompleteTrie();
trie.insert("macbook", 42);
trie.insert("mac", 10);
trie.insert("machine", 5);

console.log(trie.suggest("mac"));
